} else {
    node.ir_type == "Hash"
    inner := node.value[_]
    inner.value.ir_type == "Array"
    _find_encryption_arr(inner.value, pair)
}

_find_encryption_arr(arr, pair) {
    item := arr.value[_]
    find_encryption_disabled(item, pair)
}

find_insecure_url(node, pair) {
    node.ir_type == "Hash"
    p := node.value[_]
    has_insecure_scheme(p.value)
    pair := p
} else {
    node.ir_type == "Hash"
    inner := node.value[_]
    inner.value.ir_type == "Hash"
    find_insecure_url(inner.value, pair)
} else {
    node.ir_type == "Hash"
    inner := node.value[_]
    inner.value.ir_type == "Array"
